func buildServiceExecuteRequest(params serviceExecuteRequestParams) fizeau.ServiceExecuteRequest {
	// Prefer the catalog-resolved concrete model when present so the
	// service issues chat completions against the actual model id (not
	// the user-facing alias / routeKey). Falls back to the requested
	// model for direct provider pins where no catalog resolution ran.
	model := params.RequestedModel
	if params.ResolvedModel != "" {
		model = params.ResolvedModel
	}
	provider := params.SelectedProvider
	harness := ""
	if params.SelectedProvider != "" {
		harness = "agent"
	}
	permissions := params.Permissions
	if permissions == "" {
		permissions = "unrestricted"
	}
	req := fizeau.ServiceExecuteRequest{
		Prompt:                  params.Prompt,
		SystemPrompt:            params.SystemPrompt,
		Harness:                 harness,
		Model:                   model,
		ModelRef:                params.RequestedModelRef,
		Provider:                provider,
		WorkDir:                 params.WorkDir,
		Reasoning:               params.Reasoning,
		NoStream:                params.NoStream,
		MinPower:                params.MinPower,
		MaxPower:                params.MaxPower,
		Metadata:                params.Metadata,
		Tools:                   params.Tools,
		ToolPreset:              params.ToolPreset,
		Permissions:             permissions,
		MaxIterations:           params.MaxIterations,
		MaxTokens:               params.MaxTokens,
		ReasoningByteLimit:      params.ReasoningByteLimit,
		CompactionContextWindow: params.CompactionContextWindow,
		CompactionReserveTokens: params.CompactionReserveTokens,
		SelectedRoute:           params.SelectedRoute,
		ResolvedModelRef:        params.ResolvedModelRef,
		Temperature:             params.Temperature,
		TopP:                    params.TopP,
		TopK:                    params.TopK,
		MinP:                    params.MinP,
		RepetitionPenalty:       params.RepetitionPenalty,
		Seed:                    params.Seed,
		SamplingSource:          params.SamplingSource,
		PlanningMode:            params.PlanningMode,
	}
	return req
}

