func TestBuildToolsForPresetWithAnchors_RegistersAnchorEditAndStoreBackedRead(t *testing.T) {
	workDir := t.TempDir()
	tools := buildToolsForPresetWithAnchors(workDir, "default", true)

	var read *fizeau.ReadTool
