// Load reads configuration from .fizeau/config.yaml (project) and
// ~/.config/fizeau/config.yaml (global), with env var expansion.
// Project config overrides global config. If no config files exist,
// returns defaults.
func Load(workDir string) (*Config, error) {
	cfg := Defaults()

	// Try global config first, then project config (project wins)
	var paths []string
	if home, err := os.UserHomeDir(); err == nil {
		paths = append(paths, GlobalConfigPath(home))
	}
	paths = append(paths, ProjectConfigPath(workDir))

	for _, p := range paths {
		data, err := safefs.ReadFile(p)
		if err != nil {
			continue
		}
		expanded := expandEnvVars(string(data))
		if err := rejectLegacyProviderReasoningKeys([]byte(expanded)); err != nil {
			return nil, fmt.Errorf("config: parsing %s: %w", p, err)
		}
		if err := yaml.Unmarshal([]byte(expanded), &cfg); err != nil {
			return nil, fmt.Errorf("config: parsing %s: %w", p, err)
		}
	}

	// Migrate legacy flat format
	cfg.migrateLegacy()

	// Apply env var overrides to default provider
	cfg.applyEnvOverrides()

	if err := cfg.finalize(); err != nil {
		return nil, err
	}

	return &cfg, nil
}

// migrateLegacy converts old flat fields to a named provider.
func (c *Config) migrateLegacy() {
	if c.Providers != nil && len(c.Providers) > 0 {
		return // new format takes precedence
	}
	if c.LegacyProvider == "" && c.LegacyBaseURL == "" {
		return // nothing to migrate
	}

	provType := c.LegacyProvider
	if provType == "" {
		provType = inferProviderTypeFromBaseURL(c.LegacyBaseURL)
		if provType == "" {
			provType = "lmstudio"
		}
	}
	baseURL := c.LegacyBaseURL
	if baseURL == "" {
		baseURL = "http://localhost:1234/v1"
	}

	c.Providers = map[string]ProviderConfig{
		"default": {
			Type:    provType,
			BaseURL: baseURL,
			APIKey:  c.LegacyAPIKey,
			Model:   c.LegacyModel,
		},
	}
	if c.Default == "" {
		c.Default = "default"
	}
	c.LegacyProvider = ""
	c.LegacyBaseURL = ""
	c.LegacyAPIKey = ""
	c.LegacyModel = ""
}

// applyEnvOverrides applies AGENT_* env vars to the default provider.
func (c *Config) applyEnvOverrides() {
	if v := os.Getenv("FIZEAU_SKILLS_DIR"); v != "" {
		c.Skills.Dir = v
	}

	if c.Providers == nil {
		c.Providers = make(map[string]ProviderConfig)
	}

	// Get or create default provider
	defName := c.defaultNameForEnvOverride()
	p := c.Providers[defName]
	changed := false

	if v := os.Getenv("FIZEAU_PROVIDER"); v != "" {
		p.Type = v
		changed = true
	}
	if v := os.Getenv("FIZEAU_BASE_URL"); v != "" {
		p.BaseURL = v
		changed = true
	}
	if v := os.Getenv("FIZEAU_API_KEY"); v != "" {
		p.APIKey = v
		changed = true
	}
	if v := os.Getenv("FIZEAU_MODEL"); v != "" {
		p.Model = v
		changed = true
	}

	// Sampling overrides forwarded by the benchmark matrix adapter.
	if v := os.Getenv("FIZEAU_TEMPERATURE"); v != "" {
		if f, err := strconv.ParseFloat(v, 64); err == nil {
			if p.Sampling == nil {
				p.Sampling = &SamplingProfile{}
			}
			p.Sampling.Temperature = &f
			changed = true
		}
	}
	if v := os.Getenv("FIZEAU_TOP_P"); v != "" {
		if f, err := strconv.ParseFloat(v, 64); err == nil {
			if p.Sampling == nil {
				p.Sampling = &SamplingProfile{}
			}
			p.Sampling.TopP = &f
			changed = true
		}
	}
	if v := os.Getenv("FIZEAU_TOP_K"); v != "" {
		if n, err := strconv.Atoi(v); err == nil {
			if p.Sampling == nil {
				p.Sampling = &SamplingProfile{}
			}
			p.Sampling.TopK = &n
			changed = true
		}
	}
	if v := os.Getenv("FIZEAU_MIN_P"); v != "" {
		if f, err := strconv.ParseFloat(v, 64); err == nil {
			if p.Sampling == nil {
				p.Sampling = &SamplingProfile{}
			}
			p.Sampling.MinP = &f
			changed = true
		}
	}

	// Emit start-of-execution routing_decision so consumers know the picked
	// chain before any real work fires. The actual chain (post-fallback) is
	// stamped onto the final event's RoutingActual field.
	go s.runExecute(ctx, req, *decision, meta, inner, sessionID, overrideCtx)
	return outer, nil
}

// resolveExecuteRoute reduces the request to a concrete RouteDecision.
// The request is dispatched through the routing engine
// (internal/routing.Resolve) when under-specified, or accepted verbatim
// when Harness is set explicitly.
func (s *service) resolveExecuteRoute(req ServiceExecuteRequest) (*RouteDecision, error) {
	// If Harness is omitted, route through the engine. The engine defaults to
	// local-first and auto-selects from configured endpoints when no other
	// constraints are specified — an empty request is valid if providers exist.
	if req.Harness == "" {
		return s.resolveExecuteRouteWithEngine(req)
	}
	canonical := harnesses.ResolveHarnessAlias(req.Harness)
	if !s.registry.Has(canonical) {
		return nil, fmt.Errorf("unknown harness %q", req.Harness)
	}
	cfg, _ := s.registry.Get(canonical)
	if err := validateExplicitHarnessProfile(canonical, cfg, req.Profile); err != nil {
		return nil, err
	}
	if err := validateExplicitProvider(s.opts.ServiceConfig, cfg, req.Provider); err != nil {
		return nil, err
	}
	if err := validateExplicitHarnessModel(canonical, cfg, req.Model, req.Provider); err != nil {
		return nil, err
	}
	if err := validateExplicitHarnessReasoning(canonical, cfg, req.Reasoning); err != nil {
		return nil, err
	}
	if err := validateExplicitHarnessQuota(canonical, cfg); err != nil {
		return nil, err
	}
	resolvedModel := resolveSubprocessModelAlias(canonical, req.Model)
	decision := &RouteDecision{
		Harness:  canonical,
		Provider: req.Provider,
		Model:    resolvedModel,
		Reason:   "explicit",
		Power:    catalogPowerForModel(serviceRoutingCatalog(), resolvedModel),
	}
	if decision.Endpoint == "" {
		_, endpoint, _ := splitEndpointProviderRef(decision.Provider)
		decision.Endpoint = endpoint
	}
	return decision, nil
}

func validateExplicitHarnessQuota(name string, cfg harnesses.HarnessConfig) error {
	if !cfg.IsSubscription {
		return nil
	}
	now := time.Now()
	qs, ok := subscriptionQuotaForHarness(name, now)
	if !ok || !qs.Present || !qs.Fresh || qs.OK {
		return nil

	if opts.Stderr == nil {
		opts.Stderr = os.Stderr
	}
	if opts.Version == "" {
		opts.Version = Version
	}
	if opts.BuildTime == "" {
		opts.BuildTime = BuildTime
	}
	if opts.GitCommit == "" {
		opts.GitCommit = GitCommit
	}
	oldVersion, oldBuildTime, oldGitCommit := Version, BuildTime, GitCommit
	Version, BuildTime, GitCommit = opts.Version, opts.BuildTime, opts.GitCommit
	defer func() {
		Version, BuildTime, GitCommit = oldVersion, oldBuildTime, oldGitCommit
	}()
	return runWithOptions(opts)
}

